SELECT F.COD, COUNT(*) QTD FROM (SELECT COALESCE(NULLIF(P.FINALIDADES, ''), CONCAT_WS(',', IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'lucid|clareza|discernimento|concentra|foco|aten[cç][aã]o|mente (calma|tranquila|serena)', 'lucidez', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'depress|ansied|tristez|ang[uú]sti|medo|p[aâ]nico|emo[cç]|ang[uú]stia', 'emocional', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'negativ|mau.{0,10}pensamento|forma.?pensamento|pessimis|pensamentos? ruins?', 'negativos', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'prote|limpeza|descarrego|escudo|blind|purifica', 'protecao', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'obsess|ataque|vampiri|feiti|demanda|magia negra|esp[ií]ritos? (sofredor|trevoso|baixo)', 'obsessao', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'dormir|sono|ins[oô]nia|deitar|adormec', 'sono', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'proje[cç][aã]o|desdobramento|sonho l[uú]cido|sa[ií]da do corpo|extraf[ií]sic', 'projecao', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'sa[uú]de|cura|doen|dores? |imunid|corpo f[ií]sico', 'saude', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'prosper|dinheiro|abund[aâ]ncia|abrir caminhos|abertura de caminhos|emprego', 'prosperidade', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'perd[aã]o|perdoar|fam[ií]lia|relacion|casal|filhos? |m[aá]goa', 'relacoes', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP ' casa |ambiente| lar |c[oô]modos?|resid[eê]ncia', 'casa', NULL), IF(CONCAT(P.TITULO, ' ', P.INSTRUCAO) REGEXP 'mentor|amparador|conex[aã]o|gratid[aã]o|intui[cç]|mediun', 'conexao', NULL))) FINS FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID WHERE V.STATUS = 'ESTUDADO' AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(P.TITULO, ' ', P.INSTRUCAO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{tipo}}' = '' OR P.TIPO = '{{tipo}}')) X JOIN (SELECT 'lucidez' COD UNION ALL SELECT 'emocional' COD UNION ALL SELECT 'negativos' COD UNION ALL SELECT 'protecao' COD UNION ALL SELECT 'obsessao' COD UNION ALL SELECT 'sono' COD UNION ALL SELECT 'projecao' COD UNION ALL SELECT 'saude' COD UNION ALL SELECT 'prosperidade' COD UNION ALL SELECT 'relacoes' COD UNION ALL SELECT 'casa' COD UNION ALL SELECT 'conexao' COD) F ON FIND_IN_SET(F.COD, X.FINS) GROUP BY F.COD